import { db } from './database';

export async function getRecommendations(userId: string, limit: number = 5) {
  // Get user's purchased courses
  const purchases = await db('purchases')
    .where('user_id', userId)
    .select('course_id');

  const purchasedIds = purchases.map(p => p.course_id);

  // Find users with similar purchases
  const similarUsers = await db('purchases')
    .whereIn('course_id', purchasedIds)
    .where('user_id', '!=', userId)
    .select('user_id', 'course_id');

  // Get courses purchased by similar users
  const recommendedCourses = await db('courses')
    .whereIn('id', similarUsers.map(u => u.course_id))
    .whereNotIn('id', purchasedIds)
    .count('*')
    .groupBy('id')
    .orderBy('count', 'desc')
    .limit(limit);

  return recommendedCourses;
}

