export async function getContentBasedRecommendations(courseId: string) {
  const course = await db('courses').where('id', courseId).first();

  // Find courses with similar category and skill level
  const recommendations = await db('courses')
    .where('category', course.category)
    .where('level', course.level)
    .where('id', '!=', courseId)
    .orderBy('rating', 'desc')
    .limit(5);

  return recommendations;
}

interface Coupon {
  code: string;
  discountType: 'percentage' | 'fixed';
  discountValue: number;
  maxUses: number;
  usesLeft: number;
  expiryDate: Date;
  applicableCourses?: string[]; // null = all courses
}

export async function validateCoupon(
  code: string,
  total: number,
  courseIds: string[]
): Promise<{ valid: boolean; discount: number; message: string }> {
  const coupon = await db('coupons').where('code', code.toUpperCase()).first();

  if (!coupon) {
    return { valid: false, discount: 0, message: 'Coupon not found' };
  }

  if (coupon.expiryDate < new Date()) {
    return { valid: false, discount: 0, message: 'Coupon expired' };
  }

  if (coupon.usesLeft <= 0) {
    return { valid: false, discount: 0, message: 'Coupon usage limit reached' };
  }

  if (coupon.applicableCourses && coupon.applicableCourses.length > 0) {
    const applicable = courseIds.some(id => coupon.applicableCourses.includes(id));
    if (!applicable) {
      return { valid: false, discount: 0, message: 'Coupon not applicable to these courses' };
    }
  }

  let discount = 0;
  if (coupon.discountType === 'percentage') {
    discount = (total * coupon.discountValue) / 100;
  } else {
    discount = coupon.discountValue;
  }

  return { valid: true, discount, message: 'Coupon applied' };
}

export async function applyCoupon(code: string) {
  const coupon = await db('coupons').where('code', code.toUpperCase()).first();
  if (coupon) {
    await db('coupons').where('code', code).decrement('usesLeft');
  }
}

