import PDFDocument from 'pdfkit';
import fs from 'fs';

export async function generateInvoice(
  orderId: string,
  userId: string,
  courses: Array<{ title: string; price: number }>,
  total: number
) {
  const doc = new PDFDocument();
  const filename = `invoice_${orderId}.pdf`;

  doc.pipe(fs.createWriteStream(filename));

  // Header
  doc.fontSize(20).text('INVOICE', 100, 50);
  doc.fontSize(10).text(`Invoice Number: ${orderId}`, 100, 80);
  doc.text(`Date: ${new Date().toLocaleDateString()}`, 100, 95);

  // Customer info
  const user = await db('users').where('id', userId).first();
  doc.text(`Bill To: ${user.name}`, 100, 130);
  doc.text(`Email: ${user.email}`, 100, 145);

  // Table header
  doc.fontSize(12).text('Course', 100, 200);
  doc.text('Price', 400, 200);

  let yPosition = 230;
  let subtotal = 0;

  // Table rows
  courses.forEach((course) => {
    doc.fontSize(10).text(course.title.substring(0, 40), 100, yPosition);
    doc.text(`$${course.price.toFixed(2)}`, 400, yPosition);
    yPosition += 30;
    subtotal += course.price;
  });

  // Totals
  yPosition += 20;
  doc.fontSize(12).text('Subtotal:', 350, yPosition).text(`$${subtotal.toFixed(2)}`, 450, yPosition);
  yPosition += 25;
  doc.text('Tax:', 350, yPosition).text('$0.00', 450, yPosition);
  yPosition += 25;
  doc.fontSize(14).text('Total:', 350, yPosition).text(`$${total.toFixed(2)}`, 450, yPosition);

  doc.end();
  return filename;
}

import React, { useState } from 'react';
import { Star } from 'react-feather';

interface Review {
  id: string;
  userId: string;
  courseId: string;
  rating: number;
  title: string;
  comment: string;
  helpful: number;
  notHelpful: number;
  createdAt: Date;
}

function CourseReviews({ courseId }) {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [newRating, setNewRating] = useState(0);
  const [newComment, setNewComment] = useState('');
  const [loading, setLoading] = useState(false);

  const submitReview = async () => {
    setLoading(true);
    const response = await fetch(`/api/courses/${courseId}/reviews`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        rating: newRating,
        comment: newComment
      })
    });

    const newReview = await response.json();
    setReviews([...reviews, newReview]);
    setNewRating(0);
    setNewComment('');
    setLoading(false);
  };

  const averageRating = reviews.length > 0 
    ? reviews.reduce((sum, r) => sum + r.rating, 0) / reviews.length 
    : 0;

  return (
    <div>
      <h3>Reviews ({reviews.length})</h3>
      <div>Average Rating: {averageRating.toFixed(1)} ⭐</div>

      <div className="review-form">
        <div className="rating-input">
          {[1, 2, 3, 4, 5].map(star => (
            <Star
              key={star}
              onClick={() => setNewRating(star)}
              fill={star <= newRating ? 'gold' : 'none'}
              style={{ cursor: 'pointer' }}
            />
          ))}
        </div>
        <textarea
          value={newComment}
          onChange={(e) => setNewComment(e.target.value)}
          placeholder="Write your review..."
        />
        <button onClick={submitReview} disabled={loading}>
          Submit Review
        </button>
      </div>

      <div className="reviews-list">
        {reviews.map(review => (
          <div key={review.id} className="review-item">
            <div>{review.rating} ⭐ - {review.title}</div>
            <p>{review.comment}</p>
            <small>Helpful: {review.helpful} | Not Helpful: {review.notHelpful}</small>
          </div>
        ))}
      </div>
    </div>
  );
}

export default CourseReviews;

export async function checkInventory(courseId: string, quantity: number) {
  const course = await db('courses').where('id', courseId).first();

  if (!course || course.seats_available < quantity) {
    return { available: false, seatsAvailable: course?.seats_available || 0 };
  }

  return { available: true, seatsAvailable: course.seats_available };
}

export async function reserveInventory(courseId: string, quantity: number) {
  const reserved = await db('courses')
    .where('id', courseId)
    .decrement('seats_available', quantity)
    .increment('seats_reserved', quantity);

  return reserved > 0;
}

export async function confirmReservation(orderId: string) {
  const orderItems = await db('order_items').where('order_id', orderId);

  for (const item of orderItems) {
    await db('courses')
      .where('id', item.course_id)
      .decrement('seats_reserved', item.quantity);
  }
}

export async function cancelReservation(orderId: string) {
  const orderItems = await db('order_items').where('order_id', orderId);

  for (const item of orderItems) {
    await db('courses')
      .where('id', item.course_id)
      .decrement('seats_reserved', item.quantity)
      .increment('seats_available', item.quantity);
  }
}

import React, { useEffect, useState } from 'react';
import { Heart } from 'react-feather';

function CourseCard({ course, userId }) {
  const [isFavorited, setIsFavorited] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    checkIfFavorited();
  }, [course.id, userId]);

  const checkIfFavorited = async () => {
    const response = await fetch(
      `/api/users/${userId}/favorites/${course.id}`
    );
    const data = await response.json();
    setIsFavorited(data.isFavorited);
  };

  const toggleFavorite = async () => {
    setLoading(true);
    const method = isFavorited ? 'DELETE' : 'POST';

    await fetch(`/api/users/${userId}/favorites/${course.id}`, {
      method
    });

    setIsFavorited(!isFavorited);
    setLoading(false);
  };

  return (
    <div className="course-card">
      <img src={course.thumbnail} alt={course.title} />
      <h3>{course.title}</h3>
      <p>${course.price}</p>
      <button
        onClick={toggleFavorite}
        disabled={loading}
        className="favorite-btn"
      >
        <Heart
          fill={isFavorited ? 'red' : 'none'}
          color={isFavorited ? 'red' : 'gray'}
        />
      </button>
    </div>
  );
}

