interface TaxRate {
  state: string;
  rate: number;
  hasLocalTax: boolean;
  localRate?: number;
}

const TAX_RATES: Record<string, TaxRate> = {
  'CA': { state: 'California', rate: 0.0725, hasLocalTax: true, localRate: 0.0125 },
  'NY': { state: 'New York', rate: 0.04, hasLocalTax: true, localRate: 0.04875 },
  'TX': { state: 'Texas', rate: 0.0625, hasLocalTax: true, localRate: 0.02 },
  'FL': { state: 'Florida', rate: 0.06, hasLocalTax: false }
};

export function calculateTax(
  subtotal: number,
  stateCode: string,
  zipCode?: string
): { stateTax: number; localTax: number; total: number } {
  const taxInfo = TAX_RATES[stateCode];

  if (!taxInfo) {
    return { stateTax: 0, localTax: 0, total: subtotal };
  }

  const stateTax = subtotal * taxInfo.rate;
  const localTax = taxInfo.hasLocalTax ? subtotal * (taxInfo.localRate || 0) : 0;
  const total = subtotal + stateTax + localTax;

  return { stateTax, localTax, total };
}

