interface BulkDiscount {
  minQuantity: number;
  maxQuantity?: number;
  discountPercent: number;
}

const BULK_DISCOUNTS: BulkDiscount[] = [
  { minQuantity: 5, maxQuantity: 10, discountPercent: 5 },
  { minQuantity: 11, maxQuantity: 25, discountPercent: 10 },
  { minQuantity: 26, maxQuantity: 50, discountPercent: 15 },
  { minQuantity: 51, discountPercent: 20 }
];

export function calculateBulkDiscount(
  quantity: number,
  unitPrice: number
): { discount: number; discountPercent: number; finalPrice: number } {
  const applicable = BULK_DISCOUNTS.find(
    d => quantity >= d.minQuantity && 
         (!d.maxQuantity || quantity <= d.maxQuantity)
  );

  if (!applicable) {
    return { discount: 0, discountPercent: 0, finalPrice: unitPrice * quantity };
  }

  const discount = (unitPrice * quantity * applicable.discountPercent) / 100;
  return {
    discount,
    discountPercent: applicable.discountPercent,
    finalPrice: (unitPrice * quantity) - discount
  };
}

// B2B pricing tier
export async function getB2BPricing(
  companyId: string,
  quantity: number,
  courseId: string
) {
  const course = await db('courses').where('id', courseId).first();
  const company = await db('companies').where('id', companyId).first();

  // Check for negotiated pricing
  const negotiated = await db('b2b_pricing')
    .where('company_id', companyId)
    .where('course_id', courseId)
    .first();

  if (negotiated) {
    return {
      unitPrice: negotiated.negotiated_price,
      totalPrice: negotiated.negotiated_price * quantity,
      type: 'negotiated'
    };
  }

  // Apply bulk discount
  const bulk = calculateBulkDiscount(quantity, course.price);

  return {
    unitPrice: course.price - (course.price * bulk.discountPercent / 100),
    totalPrice: bulk.finalPrice,
    type: 'bulk',
    discountPercent: bulk.discountPercent
  };
}

export enum RefundStatus {
  PENDING = 'pending',
  APPROVED = 'approved',
  REJECTED = 'rejected',
  PROCESSING = 'processing',
  COMPLETED = 'completed'
}

const REFUND_POLICY = {
  daysToRefund: 30,
  maxRefundPercent: 100,
  nonRefundableItems: ['lifetime_access']
};

export async function requestRefund(
  orderId: string,
  reason: string,
  attachment?: string
) {
  const order = await db('orders').where('id', orderId).first();

  if (!order) {
    throw new Error('Order not found');
  }

  // Check refund eligibility
  const daysSincePurchase = Math.floor(
    (Date.now() - order.created_at.getTime()) / (1000 * 60 * 60 * 24)
  );

  if (daysSincePurchase > REFUND_POLICY.daysToRefund) {
    throw new Error('Refund period has expired');
  }

  const refundRequest = await db('refund_requests').insert({
    orderId,
    reason,
    attachment,
    status: RefundStatus.PENDING,
    createdAt: new Date()
  });

  return refundRequest;
}

export async function processRefund(
  refundId: string,
  approved: boolean,
  notes?: string
) {
  const refund = await db('refund_requests').where('id', refundId).first();
  const order = await db('orders').where('id', refund.order_id).first();

  const newStatus = approved ? RefundStatus.APPROVED : RefundStatus.REJECTED;

  await db('refund_requests')
    .where('id', refundId)
    .update({ status: newStatus, approvalNotes: notes });

  if (approved) {
    // Process payment refund
    await stripe.refunds.create({ payment_intent: order.stripe_payment_id });

    // Remove course access
    await db('enrollments')
      .where('order_id', refund.order_id)
      .delete();

    // Update refund status
    await db('refund_requests')
      .where('id', refundId)
      .update({ status: RefundStatus.COMPLETED });
  }
}

